  var sm = 0; for (var j = i - 9; j <= i; j++) sm += C[j];
  ma.push(sm / 10);
}
var lastX = xp(n - 1), lastC = C[n - 1];
// 1 gridlines and event band
for (var t = Math.ceil(yLo / 500) * 500; t <= yHi; t += 500) {
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5}));
  svg.appendChild(tx(fmt(t, 0), {x: margin.left - 6, y: yp(t) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}));
}
var bandI = 20, bx = xp(bandI) - 14;
svg.appendChild(el("rect", {x: bx, y: MT, width: 28, height: PH + GAP + VOLH, fill: "#c0392b", "fill-opacity": 0.05}));
// 2 reference lines, period high and period low
var resY = yp(hi), supY = yp(lo);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: resY, y2: resY, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: supY, y2: supY, stroke: "#7a3030", "stroke-width": 1, "stroke-dasharray": "3,3"}));
// 3 moving average
var d = "";
for (i = 0; i < n; i++) { if (ma[i] === null) continue; d += (d === "" ? "M" : "L") + xp(i).toFixed(1) + " " + yp(ma[i]).toFixed(1) + " "; }
svg.appendChild(el("path", {d: d, fill: "none", stroke: "#888888", "stroke-width": 1.4, "stroke-dasharray": "4,3"}));
// 4 axes
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: VT + VOLH, y2: VT + VOLH, stroke: "#d8d8d8", "stroke-width": 1}));
// 5 candles, volume bars, event markers
var events = [{i: 5, l1: "HAUSSE FED", l2: "16 SEPT."}, {i: 17, l1: "EMPLOIS US FAIBLES", l2: "2 OCT."}];
events.forEach(function(ev){
  var ex = xp(ev.i);
  var lw = Math.max(tw(ev.l1, 7, true), tw(ev.l2, 7, true));
  var nearRight = (ex + lw + 3) > (margin.left + PW);
  var crowded = events.some(function(o){ return o.i !== ev.i && Math.abs(xp(o.i) - ex) < 85; });
  var anchor = (crowded || nearRight) ? "end" : "start";
  var off = (crowded || nearRight) ? -4 : 3;
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: VT + VOLH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
  svg.appendChild(tx(ev.l1, {x: ex + off, y: MT + 10, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
  svg.appendChild(tx(ev.l2, {x: ex + off, y: MT + 19, "text-anchor": anchor, "font-size": 7, "font-weight": 700, fill: "#1a3560"}));
});
for (i = 0; i < n; i++) {
  var x = xp(i), up = C[i] >= O[i], col = up ? UP : DN;
  svg.appendChild(el("line", {x1: x, x2: x, y1: yp(H[i]), y2: yp(L[i]), stroke: col, "stroke-width": 1}));
  var top = yp(Math.max(O[i], C[i])), bh = Math.max(Math.abs(yp(O[i]) - yp(C[i])), 1);
  svg.appendChild(el("rect", {x: x - 7, y: top, width: 14, height: bh, fill: col}));
  var vh = VT + VOLH - vy(V[i]);
  svg.appendChild(el("rect", {x: x - 7, y: vy(V[i]), width: 14, height: vh, fill: col, "fill-opacity": 0.55}));
}
// 6 gold pill, left of the last candle, above the recent highs
var pillText = fmt(lastC, 2);
var pillW = tw(pillText, 9, false) + 10, pillH = 16;
var pillX = lastX - pillW - 14;
var pillY = yp(36050);
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}));
// 7 labels
svg.appendChild(tx("7 OCT. -1,7 %", {x: bx + 28, y: supY + 10, "text-anchor": "end", "font-size": 7, "font-weight": 700, fill: "#c0392b"}));
svg.appendChild(tx("SOMMET PÉRIODE " + fmt(hi, 2) + ", 22 SEPT.", {x: xp(10) + 4, y: resY - 4, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#2e7d32"}));
svg.appendChild(tx("CREUX PÉRIODE " + fmt(lo, 2) + ", 1ER OCT.", {x: margin.left + 4, y: supY + 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#7a3030"}));
svg.appendChild(tx("MM10", {x: xp(14), y: yp(ma[14]) - 10, "text-anchor": "middle", "font-size": 7.5, fill: "#888888"}));
svg.appendChild(tx("VOL", {x: margin.left + 4, y: VT + 9, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb"}));
svg.appendChild(tx(fmt(vmax, 0) + " M", {x: xp(7) + 10, y: vy(vmax) + 8, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb"}));
days.forEach(function(m, k){
  svg.appendChild(tx(m, {x: xp(k), y: VT + VOLH + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999"}));
});
svg.appendChild(tx("SEPTEMBRE", {x: xp(0), y: VT + VOLH + 28, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#888888"}));
svg.appendChild(tx("OCTOBRE", {x: xp(16), y: VT + VOLH + 28, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#888888"}));
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Investing.com, données historiques de l’indice composé S&amp;P/TSX (ouverture, haut, bas, clôture, volume), du 9 septembre au 8 octobre 2026&nbsp;; moyenne mobile sur 10 jours calculée à partir des clôtures. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Le volume est celui coté par Investing.com, et la lecture de 628,42 millions du 18 septembre est une valeur aberrante isolée. Les sommets et creux de la période sont intrajournaliers, la moyenne mobile sur 10 jours est calculée à partir des cours de clôture, et la Réserve fédérale a relevé sa fourchette cible le 16 septembre.</p>
<p>Le creux du 8 octobre, à 34&nbsp;952,95, est resté 14,94 points au-dessus du creux du 1er octobre, à 34&nbsp;938,01, soit le niveau de soutien qui compte sur ce graphique. Le test a été réussi, mais un gain sur un volume inférieur de 34&nbsp;% à la moyenne ne confirme pas un revirement. L’indice doit clôturer au-dessus de la moyenne sur 10 jours, à 35&nbsp;399, pour montrer que les acheteurs sont revenus, et non seulement que les vendeurs ont fait une pause.</p>
<h2>Le contexte de taux sous-jacent</h2>
<p>Les attentes de taux se sont détendues au cours de la semaine. CME FedWatch évaluait à 20&nbsp;% la probabilité d’une hausse de la Réserve fédérale à sa réunion d’octobre le 5 octobre, contre près de 71&nbsp;% une semaine plus tôt, après un rapport sur l’emploi américain plus faible, selon Reuters. Le procès-verbal de la réunion de septembre de la Fed montrait que la plupart des responsables s’attendent encore à une autre hausse avant la fin de 2026, selon Motley Fool Canada, et les données de LSEG montraient que les investisseurs s’attendent à au moins une autre hausse de la Banque du Canada d’ici la fin de l’année.</p>
<p>Le rendement des obligations du gouvernement du Canada à deux ans était de 3,25&nbsp;% le 8 octobre, celui à cinq ans de 3,60&nbsp;% et celui à dix ans de 3,93&nbsp;%, selon Trading Economics. L’Enquête sur la population active est attendue à 8&nbsp;h&nbsp;30 HE aujourd’hui, l’IPC américain suit le 14 octobre, et la Banque du Canada décide le 28 octobre. Les transactions dans le secteur de l’énergie se poursuivent en arrière-plan&nbsp;: Cenovus a convenu d’acquérir Athabasca Oil pour une valeur d’entreprise implicite de 5,7 milliards de dollars canadiens, et Suncor a convenu de vendre trois actifs extracôtiers à Ithaca Energy pour 1,2 milliard de dollars canadiens au comptant, selon Reuters.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui ont vu une baisse de 600 points mercredi sont ébranlés même si jeudi a redonné un peu. Ceux qui ont une exposition à l’or ou aux mines la ressentent le plus et veulent savoir s’ils doivent vendre sur la faiblesse ou attendre. Les clients qui détiennent de l’énergie ressentent le soulagement inverse et craignent de le rendre.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Le TSX a perdu 1,7&nbsp;% mercredi, sa plus forte baisse en une séance depuis environ un mois, et l’essentiel est venu des matériaux et des sociétés minières aurifères. Jeudi, il a regagné environ le sixième de cette perte. L’énergie s’est raffermie jeudi avec le rebond du pétrole. L’indice est environ 5&nbsp;% sous son sommet d’août et affiche toujours une hausse depuis le début de l’année. Une baisse comme celle-là, c’est ce que fait un marché à forte composante de produits de base quand l’or recule, et elle nous dit quelle partie de votre portefeuille a bougé, pas que le plan a changé. Ce que je veux vérifier, c’est la part de votre portefeuille qui se trouve dans les matériaux et l’énergie, et si cette répartition correspond toujours à vos objectifs.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients ayant des avoirs concentrés dans des sociétés minières aurifères et de métaux de base, et les clients détenant des actions individuelles qui ont annoncé une production faible.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients détenant des fonds indiciels larges du TSX, où la perte des matériaux a été en partie compensée par l’énergie.</p>
<p><strong>Incidence directe moindre&nbsp;:</strong> les clients détenant des obligations, des CPG et des liquidités, qui font face à un risque de taux et non à un risque d’actions cette semaine.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Vérifier dans chaque portefeuille client la part détenue dans les matériaux, l’or et l’énergie et noter ceux qui dépassent la pondération cible.</div>
<div class="checklist-item">Dresser la liste des clients qui détiennent des actions minières individuelles et revoir la taille de leurs positions.</div>
<div class="checklist-item">Appeler les clients ayant une exposition concentrée aux matériaux avant qu’ils ne le fassent, avec les mouvements du 7 et du 8 octobre en main.</div>
<div class="checklist-item">Examiner le résultat de l’Enquête sur la population active après 8&nbsp;h&nbsp;30 HE aujourd’hui et noter le taux de chômage par rapport au consensus de 6,5&nbsp;%.</div>
<div class="checklist-item">Inscrire l’IPC américain du 14 octobre et la décision de la Banque du Canada du 28 octobre au calendrier des mises à jour clients.</div>
<div class="checklist-item">Consigner chaque conversation et la raison de tout rééquilibrage.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Ce que la baisse du TSX signifie pour votre portefeuille<br><br>
